    // /**
    //  * @custom:selector 0x3eecaf4d
    //  */
    // function defaultDexFee() external view returns (uint256 dexFee_);

    // function defaultDDexFeeOfType(bytes4 vaultFeeTypeId) external view returns (uint256 dexFee_);

    // /**
