contract OrbitalProportionalSizeProbe is UniswapV4StandardExchangeOrbitalBufferHookCommon {
    using SafeERC20 for IERC20;

    function addLiquidity(
        uint256 a0Max,
        uint256 a1Max,
        uint256 a2Max,
